import React, { useEffect, useMemo } from "react";

import {
  Box,
  Button,
  FormControl,
  MenuItem,
  Select,
  SelectChangeEvent,
  Stack,
  Typography,
} from "@mui/material";

import {
  KeyboardArrowDownRounded,
  FilterAltRounded,
  RestartAltRounded,
} from "@mui/icons-material";

import { useForecastContext } from "../../contexts/ForecastContext";

import { useForecastEntities } from "../../features/forecast/hooks/useForecast";

import { ForecastEntity } from "../../features/forecast/types/forecast.types";

/**
 * =====================================================
 * FORECAST CONTEXT BAR (REDESIGNED)
 * =====================================================
 * The dashboard's global filter strip — horizon, metric, station
 * and scenario. Redesigned as a clean "context card" with labelled
 * fields and a reset action.
 *
 * NOTE: the old "Auto Refresh … Updated 3:01 PM" row has been
 * removed from here — background refresh now lives in the sticky
 * header (DashboardHeader) behind the refresh icon.
 */
const ForecastContextBar = () => {
  const {
    horizon,
    metric,
    entityId,
    scenario,
    setHorizon,
    setMetric,
    setEntityId,
    setScenario,
  } = useForecastContext();

  const { data, isLoading: entitiesLoading } = useForecastEntities();

  // memoised to keep effect deps stable (fixes the previous lint warning)
  const forecastEntities = useMemo<ForecastEntity[]>(() => data ?? [], [data]);

  /** Keep entity selection valid when backend entities change. */
  useEffect(() => {
    if (forecastEntities.length === 0) return;
    const exists = forecastEntities.some((e) => e.id === entityId);
    if (!exists) setEntityId(forecastEntities[0].id);
  }, [forecastEntities, entityId, setEntityId]);

  const handleHorizonChange = (e: SelectChangeEvent<string>) =>
    setHorizon(e.target.value as typeof horizon);
  const handleMetricChange = (e: SelectChangeEvent<string>) =>
    setMetric(e.target.value as typeof metric);
  const handleEntityChange = (e: SelectChangeEvent<string>) =>
    setEntityId(e.target.value);
  const handleScenarioChange = (e: SelectChangeEvent<string>) =>
    setScenario(e.target.value as typeof scenario);

  const handleReset = () => {
    setHorizon("daily");
    setMetric("burn");
    setScenario("actual");
    if (forecastEntities.length > 0) setEntityId(forecastEntities[0].id);
  };

  return (
    <Box
      sx={{
        bgcolor: "background.paper",
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 12,
        boxShadow: (t) =>
          t.palette.mode === "dark"
            ? "0 10px 30px rgba(0,0,0,0.35)"
            : "0 10px 30px rgba(16,32,62,0.05)",
        px: { xs: 2, sm: 3 },
        py: 2.5,
      }}
    >
      <Stack direction="row" alignItems="center" justifyContent="space-between" spacing={2} sx={{ mb: 2, flexWrap: "wrap" }}>
        <Stack direction="row" spacing={1.25} alignItems="center">
          <Box
            sx={{
              width: 38,
              height: 38,
              borderRadius: 2,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: "rgba(0,84,166,0.1)",
              color: "primary.main",
            }}
          >
            <FilterAltRounded fontSize="small" />
          </Box>
          <Box>
            <Typography variant="subtitle1" fontWeight={800} color="text.primary">
              Forecast Context
            </Typography>
            <Typography variant="caption" color="text.secondary">
              Filters apply across the whole dashboard
            </Typography>
          </Box>
        </Stack>

        <Button
          variant="outlined"
          size="small"
          startIcon={<RestartAltRounded />}
          onClick={handleReset}
          sx={{ flexShrink: 0 }}
        >
          Reset
        </Button>
      </Stack>

      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr",
            sm: "repeat(2, minmax(0,1fr))",
            lg: "repeat(4, minmax(0,1fr))",
          },
          gap: 2,
        }}
      >
        <Field label="Horizon">
          <Select
            value={horizon}
            onChange={handleHorizonChange}
            fullWidth
            IconComponent={KeyboardArrowDownRounded}
          >
            <MenuItem value="daily">Tactical (Daily)</MenuItem>
            <MenuItem value="monthly">Strategic (Monthly)</MenuItem>
          </Select>
        </Field>

        <Field label="Metric">
          <Select
            value={metric}
            onChange={handleMetricChange}
            fullWidth
            IconComponent={KeyboardArrowDownRounded}
          >
            <MenuItem value="burn">Burn Predictions</MenuItem>
            <MenuItem value="supply">Supply Predictions</MenuItem>
            <MenuItem value="stockpile">Stockpile Predictions</MenuItem>
          </Select>
        </Field>

        <Field label="Power Station">
          <Select
            value={entityId}
            onChange={handleEntityChange}
            fullWidth
            IconComponent={KeyboardArrowDownRounded}
          >
            {entitiesLoading && <MenuItem disabled>Loading stations…</MenuItem>}
            {!entitiesLoading && forecastEntities.length === 0 && (
              <MenuItem disabled>No stations available</MenuItem>
            )}
            {forecastEntities.map((e) => (
              <MenuItem key={e.id} value={e.id}>
                {e.label}
              </MenuItem>
            ))}
          </Select>
        </Field>

        <Field label="Scenario">
          <Select
            value={scenario}
            onChange={handleScenarioChange}
            fullWidth
            IconComponent={KeyboardArrowDownRounded}
          >
            <MenuItem value="actual">Baseline</MenuItem>
            <MenuItem value="hotdry">Hot &amp; Dry</MenuItem>
            <MenuItem value="hotwet">Hot &amp; Wet</MenuItem>
            <MenuItem value="colddry">Cold &amp; Dry</MenuItem>
            <MenuItem value="coldwet">Cold &amp; Wet</MenuItem>
          </Select>
        </Field>
      </Box>
    </Box>
  );
};

/**
 * Labelled form field wrapper.
 */
interface FieldProps {
  label: string;
  children: React.ReactNode;
}

/**
 * Labelled form field wrapper — the label sits ABOVE the field (outside
 * the border) so it never overlaps or gets clipped by the input border.
 */
const Field = ({ label, children }: FieldProps) => (
  <FormControl fullWidth>
    <Typography
      variant="caption"
      sx={{
        mb: 0.75,
        ml: 0.25,
        fontWeight: 700,
        color: "text.secondary",
      }}
    >
      {label}
    </Typography>
    {children}
  </FormControl>
);

export default ForecastContextBar;
